python3 -c "
import json

with open('/home/ubuntu/.agent-ml-research-be-idea-gen-0515/projects/meta_brain_lora_routing/logs/workers/worker_debug_eval_variance_p0_20260516T211958.log') as f:
    lines = f.readlines()

# Get tool results for the last few SSH commands (eval output JSONs + seed grep)
results = []
for line in lines:
    try:
        msg = json.loads(line)
        if msg.get('type') == 'user':
            content = msg.get('message', {}).get('content', [])
            for block in content:
                if block.get('type') == 'tool_result':
                    r = block.get('content', '')
                    if isinstance(r, str) and len(r) > 50:
                        results.append(r[:2000])
    except:
        pass

# Print results from the seed and noise investigation (around index 40-50)
for i, r in enumerate(results[-12:]):
    print(f'=== Result {len(results)-12+i} ===')
    # Parse the nested JSON
    try:
        parsed = json.loads(r)
        data = parsed.get('result', r)
        if isinstance(data, str):
            inner = json.loads(data)
            stdout = inner.get('data', {}).get('stdout', '')
            print(stdout[:1500])
        else:
            print(str(data)[:1500])
    except:
        print(r[:1500])
    print()
" 2>/dev/null
